      var evs = r.slice(0, 4).map(function (y) { var tm = String(y[2] || '').match(/\d{1,2}:\d{2}/); return '<div><b>' + esc(y[0].charAt(0)) + '</b><span>' + esc(tm ? tm[0] : (y[2] || '')) + '</span><em>' + esc(y[1] || '') + '</em></div>'; }).join('');
